// index.js
import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import {
  Modal,
  ComposedModal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
} from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  const [openModal, setOpenModal] = useState(false);
  const [openComposed, setOpenComposed] = useState(false);

  return (
    <div style={{ padding: 16 }}>
      <Button onClick={() => setOpenModal(true)}>
        Open Modal (danger)
      </Button>
      <Button
        onClick={() => setOpenComposed(true)}
        style={{ marginLeft: 8 }}>
        Open ComposedModal (danger)
      </Button>

      {/* Regular Modal: danger=true sets secondary to 'secondary' */}
      <Modal
        open={openModal}
        danger
        modalHeading="Delete Application"
        modalLabel="Danger Modal Example"
        secondaryButtonText="Cancel"
        primaryButtonText="Delete"
        onRequestClose={() => setOpenModal(false)}
        onRequestSubmit={() => setOpenModal(false)}
      >
        <p>This action cannot be undone. Are you sure you want to delete?</p>
      </Modal>

      {/* ComposedModal: danger=true currently sets secondary to 'tertiary' */}
      <ComposedModal
        open={openComposed}
        danger
        onClose={() => setOpenComposed(false)}>
        <ModalHeader
          label="Danger ComposedModal Example"
          title="Reset Customizations"
        />
        <ModalBody>
          <p>
            This action cannot be undone. Are you sure you want to reset all
            customizations?
          </p>
        </ModalBody>
        <ModalFooter
          secondaryButtonText="Cancel"
          primaryButtonText="Reset"
        />
      </ComposedModal>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

// index.html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Carbon Danger Modal Repro</title>
</head>
<body>
  <div id="root"></div>
  <script src="index.js"></script>
</body>
</html>
